import{G as e,W as t,n,rt as r}from"./chunks/framework.BR9-gX-M.js";var i=JSON.parse(`{"title":"Limits - automatica11y","description":"","frontmatter":{},"headers":[],"relativePath":"limits.md","filePath":"limits.md"}`),a={name:`limits.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="limits" tabindex="-1">Limits. <a class="header-anchor" href="#limits" aria-label="Permalink to “Limits.”">​</a></h1><ul><li>Automated rules find only part of what WCAG covers. They can&#39;t judge whether alt text is meaningful, whether link and heading text make sense in context, cognitive load, real focus and reading order in use, or how real screen readers behave. A person has to check those.</li><li>Components are tested in the states a fixture shows. Dialogs, menus, tooltips, and comboboxes run closed and open, and live regions run before and after the message. Other states aren&#39;t visited.</li><li>Content on a canvas with no alternative, or inside a closed shadow root, can&#39;t be tested, and the report says so. The virtual screen reader can&#39;t read inside shadow roots at all.</li><li>Motion driven by JavaScript timers, such as a carousel that animates with <code>requestAnimationFrame</code>, isn&#39;t visible to the reduced motion check.</li><li>A Svelte library that imports SvelteKit-only modules (<code>$app/environment</code> and the like) can&#39;t run on its own. The target fails, and the report names the import.</li><li>Vue 2, Svelte 4 and older, Angular older than version 22, and other frameworks report &quot;unsupported framework.&quot; Their Storybooks work, because a Storybook renders stories in a page whatever the framework.</li><li>Native screen readers aren&#39;t part of this version.</li><li>Results are a snapshot. The tools run at their latest versions, and the report records them.</li></ul><h2 id="license" tabindex="-1">License. <a class="header-anchor" href="#license" aria-label="Permalink to “License.”">​</a></h2><p>MIT. See <a href="https://github.com/thedannywahl/automatica11y/blob/main/LICENSE" target="_blank" rel="noreferrer">LICENSE</a>. The WCAG data below has its own terms.</p><h2 id="attribution" tabindex="-1">Attribution. <a class="header-anchor" href="#attribution" aria-label="Permalink to “Attribution.”">​</a></h2><p>automatica11y reads WCAG criterion numbers, names, levels, and versions from the W3C&#39;s published JSON, <a href="https://www.w3.org/WAI/WCAG22/wcag.json" target="_blank" rel="noreferrer">wcag.json</a>. The package ships that file in <code>src/data/</code> without changes.</p><p>Source: <a href="https://www.w3.org/TR/WCAG22/" target="_blank" rel="noreferrer">Web Content Accessibility Guidelines (WCAG) 2.2</a>, W3C. The JSON is used under the <a href="https://github.com/w3c/wcag/blob/main/11ty/json/README.md" target="_blank" rel="noreferrer">terms in the W3C WCAG repository</a>: the source is credited with a link, and the content isn&#39;t changed. See also the <a href="https://www.w3.org/copyright/document-license/" target="_blank" rel="noreferrer">W3C Document License</a> and <a href="https://www.w3.org/copyright/intellectual-rights/" target="_blank" rel="noreferrer">W3C Intellectual Rights</a>. The links that reports build to each criterion are added by automatica11y and aren&#39;t part of the W3C data.</p><p>Every report repeats this credit in its closing section. To refresh the data, run <code>npm run update-wcag</code>.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};